import{_ as l,o as e,c as a,a2 as t}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"畫作教學","description":"建造地圖畫的基本教學。","frontmatter":{"title":"畫作教學","description":"建造地圖畫的基本教學。"},"headers":[],"relativePath":"tutorial/painting/index.md","filePath":"tutorial/painting.md"}'),o={name:"tutorial/painting/index.md"};function r(c,i,d,n,p,h){return e(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="畫作教學" tabindex="-1">畫作教學 <a class="header-anchor" href="#畫作教學" aria-label="Permalink to &quot;畫作教學&quot;">​</a></h1><h2 id="安裝模組" tabindex="-1">安裝模組 <a class="header-anchor" href="#安裝模組" aria-label="Permalink to &quot;安裝模組&quot;">​</a></h2><h3 id="確認路徑" tabindex="-1">確認路徑 <a class="header-anchor" href="#確認路徑" aria-label="Permalink to &quot;確認路徑&quot;">​</a></h3><p>在安裝模組之前，你需要先找到Minecraft的資料夾才有辦法安裝模組</p><ol><li><p>打開<code>檔案總管</code>，然後在左側選單找到<code>本機</code>並點擊<br><img src="https://i.imgur.com/U1jAD4E.png" style="width:80%;"></p></li><li><p>點擊你當初安裝Minecraft的<code>硬碟</code><img src="https://i.imgur.com/13BH9G6.png" style="width:80%;"></p></li><li><p>在畫面的上方找到<code>檢視</code>，然後把<code>隱藏的項目</code>勾選起來<br><img src="https://i.imgur.com/qEIapPA.png" style="width:80%;"></p></li><li><p>如圖示依序找到<code>.minecraft</code>資料夾，其中<code>Nuko</code>會是你電腦的使用者名稱<br><img src="https://i.imgur.com/Da8lqp3.png" style="width:80%;"></p></li><li><p>這邊都是Minecraft的遊戲資料，然後點擊<code>mods</code>資料夾，沒有的話就自己新增資料夾<br><img src="https://i.imgur.com/GgIQJOd.png" style="width:80%;"></p></li><li><p>裡面會有你所有的模組。記住這個路徑，等等安裝會用到<br><img src="https://i.imgur.com/JH8uTbQ.png" style="width:80%;"></p></li></ol><h3 id="下載模組" tabindex="-1">下載模組 <a class="header-anchor" href="#下載模組" aria-label="Permalink to &quot;下載模組&quot;">​</a></h3><p>這邊示範的是基於fabric(設定檔)的litematica(藍圖/投影)模組<br> 依照下列的列表下載模組後，把檔案丟到剛剛的<code>mod</code>資料夾</p><h4 id="模組列表" tabindex="-1">模組列表 <a class="header-anchor" href="#模組列表" aria-label="Permalink to &quot;模組列表&quot;">​</a></h4><p>這邊不會提供下載連結，請自行將關鍵字貼到google搜尋</p><ul><li>必要 <ul><li>fabric <ul><li>設定檔，沒有它你就不用裝了</li></ul></li><li>fabric-api <ul><li>前置模組，沒有它你就不用裝了</li></ul></li><li>malilib <ul><li>前置模組，沒有它你就不用裝了</li></ul></li><li>litematica <ul><li>藍圖/投影模組，不裝它的話就可以關掉這篇教學了</li></ul></li></ul></li><li>可選 <ul><li>OptiFine <ul><li>可以運行光影包、調整進階顯示設定的設定檔，在此不另外介紹</li></ul></li><li>optifabric <ul><li>讓你能在fabric設定檔中運行Optifine的模組</li></ul></li><li>modmune <ul><li>可查看你所安裝的模組</li></ul></li><li>小地圖 <ul><li>小地圖的種類很多，找自己喜歡的來裝就好了</li></ul></li></ul></li></ul><h3 id="安裝fabric" tabindex="-1">安裝fabric <a class="header-anchor" href="#安裝fabric" aria-label="Permalink to &quot;安裝fabric&quot;">​</a></h3><ol><li><p>點擊你剛剛放進<code>mods</code>資料夾的<code>fabric-installer</code>並執行<br><img src="https://i.imgur.com/BcZt1BE.png" style="width:80%;"></p></li><li><p>在這個畫面選擇<code>客戶端</code>、<code>Minecraft版本</code>(你要遊玩的版本)、<code>載入程式版本</code>(通常選擇最新即可)<br><img src="https://i.imgur.com/wOnChjc.png" style="width:80%;"></p></li><li><p>確認安裝位置是在<code>.minecraft</code>資料夾裡，不是的話照前面的步驟找到並選擇它<br><img src="https://i.imgur.com/pYb32bv.png" style="width:80%;"></p></li><li><p>確認沒問題後按下安裝並等待完成即可</p></li></ol><h3 id="安裝optifine-補充" tabindex="-1">安裝OptiFine(補充) <a class="header-anchor" href="#安裝optifine-補充" aria-label="Permalink to &quot;安裝OptiFine(補充)&quot;">​</a></h3><ol><li><p>點擊你剛剛放進<code>mods</code>資料夾的<code>OptiFine_1.xx.x_HD_U_Hx</code>並執行<br><img src="https://i.imgur.com/MtcTc1B.png" style="width:80%;"></p></li><li><p>確認安裝位置是在<code>.minecraft</code>資料夾裡，不是的話照前面的步驟找到並選擇它<br><img src="https://i.imgur.com/wLtOhUr.png" style="width:80%;"></p></li><li><p>確認沒問題後按下安裝並等待完成即可</p></li></ol><h3 id="進入遊戲" tabindex="-1">進入遊戲 <a class="header-anchor" href="#進入遊戲" aria-label="Permalink to &quot;進入遊戲&quot;">​</a></h3><ol><li><p>打開<code>Minecraft Launcher</code></p></li><li><p>在設定檔選單中選擇剛剛安裝好的<code>fabric loader</code>，然後開始遊戲<br><img src="https://i.imgur.com/Eus5yiH.png" style="width:80%;"></p></li><li><p>在單人世界測試模組都能正常運作即完成安裝</p></li></ol><h3 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h3><ul><li>本教學內容僅供參考，必要時請自行利用google搜尋相關資源 <ul><li>大部分模組資源都是以英文撰寫，如果看不懂可以試著丟到google翻譯</li></ul></li><li>強烈建議對電腦操作有一定了解再執行這些操作，避免操作失誤導致電腦無法正常運作 <ul><li>建議事先將<code>.minecraft</code>資料夾完整備份，以方便必要時還原資料</li></ul></li><li>模組下載時請注意版本，強烈建議與你遊玩的版本完全一致，避免發生錯誤 <ul><li>部分情況下可能還是會發生錯誤，屆時請進行交叉測試找出發生問題的模組 <ul><li>有時候選擇較舊版本(模組版本，不是指Minecraft版本)的模組可能會改善此問題</li></ul></li></ul></li></ul><h2 id="litematica入門" tabindex="-1">litematica入門 <a class="header-anchor" href="#litematica入門" aria-label="Permalink to &quot;litematica入門&quot;">​</a></h2>',19)])])}const m=l(o,[["render",r]]);export{u as __pageData,m as default};
